package android.graphics; public class BitmapFactory {public static class Options {public boolean inJustDecodeBounds,inScaled;public int outWidth,outHeight,inSampleSize;} public static Bitmap output;public static int width=200,height=200,calls,sample;public static boolean failure;public static Runnable after;public static Bitmap decodeByteArray(byte[] b,int o,int l,Options options){calls++;if(failure)throw new IllegalArgumentException();if(options.inJustDecodeBounds){options.outWidth=width;options.outHeight=height;return null;}sample=options.inSampleSize;if(after!=null)after.run();return output;} }